public class Main {
    // مصفوفة ديناميكية: تتسع عند الامتلاء
    static class DynamicArray {
        private int[] data;
        private int size;

        public DynamicArray() {
            data = new int[2];
            size = 0;
        }

        public void add(int value) {
            if (size == data.length) {
                data = Arrays.copyOf(data, data.length * 2); // مضاعفة السعة
            }
            data[size++] = value;
        }

        public int get(int index) {
            return data[index];
        }

        public int size() {
            return size;
        }
    }

    public static void main(String[] args) {
        DynamicArray arr = new DynamicArray();
        for (int i = 1; i <= 5; i++) {
            arr.add(i * 10);
        }
        for (int i = 0; i < arr.size(); i++) {
            System.out.println(arr.get(i));
        }
    }
}

public class Main {
    // إقليدس: gcd(a,b) = gcd(b, a%b) حتى يصبح الباقي صفراً
    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        int a = 56, b = 98;
        System.out.println("GCD of " + a + " and " + b + " is " + gcd(a, b));
        a = 17; b = 13;
        System.out.println("GCD of " + a + " and " + b + " is " + gcd(a, b));
    }
}

